    if is_oncleanup_call(node, source) {
        let mut ids = HashSet::new();
        let mut names = HashSet::new();
        collect_identifiers(node, source, &mut ids);
        collect_function_call_names(node, source, &mut names);
        for id in ids.difference(&names) {
            cleanup_refs.insert(id.clone());
        }
    }
    for child in node.children {
        collect_mocup_info(child, source, cleared, cleanup_refs);
    }
}
